function closeTransientMenus(event){
  const target=event.target instanceof Element?event.target:null;
  if(!target?.closest('.wfm-dropdown-wrap')){
    document.querySelectorAll('.wfm-dropdown-menu.show').forEach(menu=>{
      menu.classList.remove('show');
      menu.previousElementSibling?.setAttribute('aria-expanded','false');
    });
  }
  const supervisionMenu=document.getElementById('supervision-items');
  if(supervisionMenu&&!target?.closest('[data-supervision-menu]')){
    supervisionMenu.hidden=true;
    state.supervisionOpen=false;
    document.getElementById('supervision-toggle')?.setAttribute('aria-expanded','false');
  }
}
