// CSP bloquea los atributos de evento inline. La interfaz histórica genera esos
// atributos dentro de plantillas; este puente los interpreta sin eval/new Function
// y los ejecuta mediante listeners del documento hasta completar la migración.
function splitHandlerArguments(source){const result=[];if(!source.trim())return result;let current='',quote='',depth=0,escaped=false;for(const character of source){if(escaped){current+=character;escaped=false;continue}if(character==='\\'){current+=character;escaped=true;continue}if(quote){current+=character;if(character===quote)quote='';continue}if(character==='"'||character==="'"){quote=character;current+=character;continue}if(character==='('){depth++;current+=character;continue}if(character===')'){depth--;current+=character;continue}if(character===','&&depth===0){result.push(current.trim());current='';continue}current+=character}if(current.trim())result.push(current.trim());return result}
function decodeHandlerString(value){return value.slice(1,-1).replace(/\\([\\'"nrt])/g,(_,character)=>({n:'\n',r:'\r',t:'\t'}[character]||character))}
function handlerArgument(value,element,event){const token=value.trim();if(token==='this')return element;if(token==='event')return event;if(token==='true')return true;if(token==='false')return false;if(token==='null')return null;if(/^-?\d+(?:\.\d+)?$/.test(token))return Number(token);const urlMatch=token.match(/^new URLSearchParams\((['"])([\s\S]*)\1\)$/);if(urlMatch)return new URLSearchParams(decodeHandlerString(urlMatch[1]+urlMatch[2]+urlMatch[1]));if((token.startsWith("'")&&token.endsWith("'"))||(token.startsWith('"')&&token.endsWith('"')))return decodeHandlerString(token);return undefined}
function executeCspHandler(code,element,event){const source=String(code||'').trim();if(!source)return false;if(source==="this.closest('dialog').close()"){element.closest('dialog')?.close();return true}const conditional=source.match(/^if\(event\.key===['"]Enter['"]\)([\s\S]+)$/);if(conditional){if(event.key!=='Enter')return true;return executeCspHandler(conditional[1],element,event)}const assignment=source.match(/^state\.([A-Za-z_$][\w$]*)=this\.value(?:;([\s\S]+))?$/);if(assignment){state[assignment[1]]=element.value;if(assignment[2])executeCspHandler(assignment[2],element,event);return true}if(source==='toggleQuoteMobile();saveQuoteDraft()'){toggleQuoteMobile();saveQuoteDraft();return true}if(source==='toggleQuoteTolls();saveQuoteDraft()'){toggleQuoteTolls();saveQuoteDraft();return true}const call=source.match(/^([A-Za-z_$][\w$]*)\(([\s\S]*)\)$/);if(!call)return false;const fn=window[call[1]];if(typeof fn!=='function')return false;const args=splitHandlerArguments(call[2]).map(value=>handlerArgument(value,element,event));if(args.some(value=>value===undefined))return false;fn(...args);return true}
