 const selected=state.selectedStandardDept||'MONTEVIDEO',departmentRows=rows.filter(row=>normalizeDept(row.department)===selected),displayName=departmentRows[0]?.department||selected,params=new URLSearchParams({department:displayName});if(state.standardService)params.set('service',state.standardService);if(state.standardZone)params.set('zone',state.standardZone);
 const [guidance,zones,zoneCoverage]=await Promise.all([api(`/api/arrival-guidance?${params}`),api(`/api/zones?department=${encodeURIComponent(displayName)}`),api(`/api/zones-coverage?department=${encodeURIComponent(displayName)}`)]);window.zoneCache=zones;
 const activeDelays=guidance.active_delays||[],staleDelays=guidance.delays_needing_review||[],visibleStandards=guidance.standards||[],services=[...new Set(visibleStandards.map(row=>row.service))];
 const liveNotice=activeDelays.length?`<div class="arrival-live-warning"><strong>Demora vigente y verificada: comunicá esta indicación</strong><p>Reemplaza temporalmente las referencias habituales.</p>${activeDelays.map(row=>`<div><b>${esc(row.service)}</b> · ${esc(row.zone)} — ${esc(row.message==='Margen de'&&row.minutes?`Margen de ${row.minutes} minutos`:row.message)} <small>revisar ${fmt(row.review_due_at)}</small></div>`).join('')}</div>`:staleDelays.length?`<div class="arrival-review-warning"><strong>No informes un tiempo todavía</strong><p>Hay ${staleDelays.length===1?'una demora pendiente':'demoras pendientes'} de verificación para esta consulta.</p>${staleDelays.map(row=>`<div>${esc(row.service)} · ${esc(row.zone)}</div>`).join('')}</div>`:`<div class="arrival-live-clear"><strong>Sin demoras vigentes verificadas</strong><span>${esc(guidance.operator_message)}</span></div>`;
