 const departmentCoverage=coverage.filter(item=>normalizeDept(item.department)===selected),pendingCoverage=departmentCoverage.filter(item=>item.coverage==='PENDING'),zoneGaps=zoneCoverage.filter(item=>item.coverage==='PENDING'),coveragePanel=(can('settings.manage')||can('standards.approve'))?`<div class="coverage-summary ${pendingCoverage.length||zoneGaps.length?'has-gaps':'complete'}"><strong>${zoneGaps.length?`${zoneGaps.length} brechas en zonas con cobertura esperada`:pendingCoverage.length?`${pendingCoverage.length} prestaciones sin referencia utilizable`:'Cobertura operativa completa'}</strong><span>${pendingCoverage.length||zoneGaps.length?'Los espacios quedan visibles y no se completan con tiempos supuestos.':'Todas las prestaciones configuradas tienen una referencia vigente.'}</span>${zoneGaps.length?`<div>${zoneGaps.map(item=>`<span class="coverage-gap">${esc(item.zone)} · ${esc(item.service)} · ${esc(item.owner)}</span>`).join('')}</div>`:pendingCoverage.length?`<div>${pendingCoverage.map(item=>`<span class="coverage-gap">${esc(item.service)}</span>`).join('')}</div>`:''}</div>`:'';
