 const range=state.scheduleView==='week'?`Semana del ${scheduleDateLabel(state.scheduleWeek)}`:`${state.scheduleFrom||'Todo el historial'}${state.scheduleTo?` al ${state.scheduleTo}`:''}`;
 const filters=`<div class="panel filter-panel schedule-filter-panel"><div class="schedule-filter-head"><div class="view-tabs"><button class="mini-tab ${state.scheduleView==='week'?'active':''}" onclick="setScheduleView('week')">Semana</button><button class="mini-tab ${state.scheduleView==='history'?'active':''}" onclick="setScheduleView('history')">Historial</button></div>${state.scheduleView==='week'?`<div class="schedule-week-nav"><button class="row-action" onclick="changeScheduleWeek(-7)" aria-label="Semana anterior">‹</button><strong>${esc(range)}</strong><button class="row-action" onclick="changeScheduleWeek(7)" aria-label="Semana siguiente">›</button><button class="row-action" onclick="setScheduleWeekToday()">Esta semana</button></div>`:''}</div><div class="schedule-filter-grid"><label>Persona<select onchange="state.scheduleEmployee=this.value;render()"><option value="team" ${state.scheduleEmployee==='team'?'selected':''}>Todo el equipo</option><option value="mine" ${state.scheduleEmployee==='mine'?'selected':''}>Mis horarios</option>${peopleOptions}</select></label><label>Rol<select onchange="state.scheduleRole=this.value;render()"><option value="">Todos los roles</option><option ${state.scheduleRole==='Telefonista'?'selected':''}>Telefonista</option><option ${state.scheduleRole==='Planificador'?'selected':''}>Planificador</option><option ${state.scheduleRole==='Supervisor'?'selected':''}>Supervisor</option></select></label>${state.scheduleView==='history'?`<label>Desde<input type="date" value="${esc(state.scheduleFrom)}" onchange="state.scheduleFrom=this.value"></label><label>Hasta<input type="date" value="${esc(state.scheduleTo)}" onchange="state.scheduleTo=this.value"></label>`:''}<label class="schedule-search-field">Buscar<input class="wide-search" placeholder="Turno, nota o persona" value="${esc(state.scheduleSearch)}" oninput="state.scheduleSearch=this.value;scheduleSearchChanged()" onkeydown="if(event.key==='Enter')applyScheduleSearch()"></label><div class="schedule-filter-actions"><button class="row-action" onclick="applyScheduleSearch()">Aplicar filtros</button><button class="row-action" onclick="clearScheduleFilters()">Limpiar</button></div></div></div>`;
 const report=can('reports.export')?`<button class="row-action" onclick="downloadOperationalReport('schedules',new URLSearchParams('${scheduleReportParams().toString()}'))">Descargar reporte</button>`:'';
 const columns=[['Fecha',r=>`<strong>${esc(scheduleDateLabel(r.schedule_date))}</strong><small class="schedule-week-label">Semana ${esc(r.week_start)}</small>`],['Persona','display_name'],['Rol',r=>esc(r.role_name)],['Horario publicado',r=>publishedScheduleSummary(r)],['Origen',r=>r.source==='legacy'?'Histórico':`WFM #${esc(r.revision)}`]];
 const result=state.scheduleView==='week'?scheduleWeekGrid(rows,people):table(columns,rows,()=>'', 'No hay horarios para el período y filtros seleccionados.');
