 const tabs=`<div class="settings-tabs"><button class="settings-tab ${state.settingsTab==='general'?'active':''}" onclick="selectSettingsTab('general')">General</button><button class="settings-tab ${state.settingsTab==='news'?'active':''}" onclick="selectSettingsTab('news')">Novedades</button><button class="settings-tab ${state.settingsTab==='users'?'active':''}" onclick="selectSettingsTab('users')">Usuarios</button><button class="settings-tab ${state.settingsTab==='roles'?'active':''}" onclick="selectSettingsTab('roles')">Roles y permisos</button><button class="settings-tab ${state.settingsTab==='google'?'active':''}" onclick="selectSettingsTab('google')">Acceso Google</button><button class="settings-tab ${state.settingsTab==='quotes'?'active':''}" onclick="selectSettingsTab('quotes')">Tarifas cotizador</button><button class="settings-tab ${state.settingsTab==='catalogs'?'active':''}" onclick="selectSettingsTab('catalogs')">Catálogos</button></div>`;
 let body='';
 if(state.settingsTab==='users')body=`<div class="panel user-table-wrap"><div class="settings-intro"><div><h2>Usuarios del sistema</h2><p>Solo podrán ingresar correos corporativos registrados y activos.</p></div><button class="primary" onclick="openUserForm()">+ Crear usuario</button></div></div>`+table([['Nombre','display_name'],['Correo corporativo',r=>esc(r.email||'Sin correo asignado')],['Usuario alternativo','username'],['Rol','role_name'],['Google',r=>r.google_linked?badge('VINCULADO'):'Pendiente'],['Estado',r=>r.active?badge('ACTIVO'):badge('INACTIVO')],['Acción',r=>`<button class="row-action" onclick="openEditUser(${r.id})">Editar</button>`]],users);
 else if(state.settingsTab==='roles'){const role=roles.find(r=>r.id===state.selectedRole)||roles[0],locked=role?.name==='Administrador';body=`<div class="roles-toolbar"><div><strong>Roles y permisos</strong><span>El Administrador conserva siempre acceso completo.</span></div><button class="primary" onclick="openRoleForm()">+ Crear rol</button></div><div class="roles-layout"><div class="role-list"><div class="role-list-header">Roles disponibles</div>${roles.map(r=>`<button class="role-choice ${r.id===role.id?'active':''}" onclick="selectRole(${r.id})"><strong>${esc(r.name)}</strong><span>${r.permissions.length} permisos habilitados</span></button>`).join('')}</div><div class="permission-panel ${locked?'permissions-locked':''}"><div class="permission-head"><div><h2>${esc(role.name)}</h2><p>${locked?'Acceso completo protegido: estos permisos no pueden desactivarse.':'Seleccioná las funciones a las que puede acceder este rol.'}</p></div>${badge(role.name.toUpperCase())}</div><div class="permission-grid">${permissions.map(p=>`<label class="permission-option"><input type="checkbox" data-role-permission value="${esc(p.key)}" ${role.permissions.includes(p.key)?'checked':''} ${locked?'disabled':''}><span><strong>${esc(p.label)}</strong><small>${permissionHint(p.key)}</small></span></label>`).join('')}</div>${locked?'':`<div class="permission-actions"><button class="primary" onclick="saveRolePermissions(${role.id})">Guardar permisos</button></div>`}</div></div>`}
 else if(state.settingsTab==='google')body=googleAccessForm(await api('/api/settings/google-access'));
 else if(state.settingsTab==='quotes')body=quoteRulesForm(await api('/api/settings/quote-rules'));
 else if(state.settingsTab==='news'){const version=await api('/api/settings/version'),releases=Array.isArray(version.releases)?version.releases:[];body=`<div class="version-layout"><div class="panel version-card"><span>Versión actual</span><strong>v${esc(version.version)}</strong><small>Publicada el ${esc(version.released_label||version.released)}</small></div><div class="panel release-notes"><h3>Registro de actualizaciones</h3><p>${releases.length} versiones documentadas, desde la más reciente hasta la primera entrega.</p></div></div><section class="release-history" aria-label="Historial de novedades">${releases.map((release,index)=>`<details class="panel release-entry" ${index===0?'open':''}><summary><span><strong>Versión ${esc(release.version)}</strong>${release.title?`<small>${esc(release.title)}</small>`:''}</span><span class="release-date">${esc(release.released_label||release.released)} · ${release.notes.length} cambio${release.notes.length===1?'':'s'}</span></summary><ul>${release.notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul></details>`).join('')}</section>`}
 else if(state.settingsTab==='general')body=`<div class="panel schedule-settings-card"><div><h3>Horarios del equipo</h3><p>Configurá turnos de Telefonistas, Planificadores y Supervisores. Cada registro queda asociado a su semana para consultar el historial.</p></div><button class="primary" onclick="openScheduleForm()">+ Configurar horario</button></div>`
 else if(state.settingsTab==='catalogs')body=renderTollCatalog(await api('/api/settings/tolls'));
