function bindQuoteMapResize(){const resizer=$('.quote-map-resizer'),handle=$('.quote-map-handle');if(!resizer||!handle)return;handle.onpointerdown=event=>{event.preventDefault();const startY=event.clientY,startHeight=resizer.getBoundingClientRect().height;handle.setPointerCapture?.(event.pointerId);document.body.style.cursor='ns-resize';document.body.style.userSelect='none';const move=moveEvent=>{const height=Math.max(418,Math.min(window.innerHeight*.85,startHeight+moveEvent.clientY-startY));resizer.style.height=`${height}px`;window.quoteLeafletMap?.invalidateSize({pan:false})};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);document.body.style.cursor='';document.body.style.userSelect='';window.quoteLeafletMap?.invalidateSize({pan:false})};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)}}
function updateQuoteOptions(){const special=$('#special'),gavilan=$('#gavilan');if(!special||!gavilan)return;if(gavilan.checked){special.checked=false;special.disabled=true;gavilan.disabled=false}else if(special.checked){gavilan.checked=false;gavilan.disabled=true;special.disabled=false}else{special.disabled=false;gavilan.disabled=false}}
async function calculateQuote(event){event.preventDefault();const form=new FormData(event.target),body=Object.fromEntries(form);for(const key of ['include_mobile','include_tolls','special','gavilan'])body[key]=form.has(key);body.uninsured=body.coverage==='uninsured';delete body.coverage;body.manual_distance=state.quoteMode==='manual';if(!body.include_mobile){body.manual_mobile_km=0;body.mobile_origin=null}if(!body.manual_distance||!body.include_tolls)delete body.manual_toll_count;const button=event.target.querySelector('button[type="submit"]'),original=button.textContent;button.disabled=true;button.textContent=body.manual_distance?'Calculando...':'Trazando recorrido...';try{state.quoteResult=await api('/api/quotes/calculate',{method:'POST',body:JSON.stringify(body)});state.quoteError='';state.quoteFallbackAvailable=false;state.quoteResult._input=body;saveQuoteDraft();$('#quote-result').innerHTML=quoteResultHtml(state.quoteResult);renderQuoteMap(state.quoteResult);toast('Cotización guardada en el historial')}catch(error){state.quoteResult=null;state.quoteError=readableError(error,'Faltan campos por completar o hay datos inválidos');state.quoteFallbackAvailable=!body.manual_distance;$('#quote-result').innerHTML=quoteResultHtml(null);toast(state.quoteError)}finally{button.disabled=false;button.textContent=original}}
function quoteDraftKey(){return `centroQuoteDraft:${authUser?.id||currentUser||'usuario'}`}
function loadQuoteDraft(){try{const draft=JSON.parse(localStorage.getItem(quoteDraftKey())||'null');if(draft?.mode)state.quoteMode=draft.mode;return draft}catch{return null}}
function saveQuoteDraft(){const form=$('#quote-form');if(!form)return;const formData=new FormData(form),data=Object.fromEntries(formData);data.coverage=data.coverage||(formData.has('uninsured')?'uninsured':'insured');data.uninsured=data.coverage==='uninsured';for(const key of ['include_mobile','include_tolls','special','gavilan'])data[key]=formData.has(key);data.mode=state.quoteMode;localStorage.setItem(quoteDraftKey(),JSON.stringify(data))}
