function clearQuoteDraft(){localStorage.removeItem(quoteDraftKey());state.quoteRestore=null;state.quoteResult=null;render()}
function recoverQuote(id){const row=(window.quoteCache||[]).find(item=>item.id===id);if(!row)return;const manual=row.origin_input==='Cotización manual',snapshot=quotePricingSnapshot(row);state.quoteMode=manual?'manual':'automatic';state.quoteRestore={task_number:row.task_number,origin_input:manual?'':row.origin_input,destination_input:manual?'':row.destination_input,mobile_input:row.mobile_input,manual_trip_km:row.trip_km,manual_mobile_km:row.mobile_km,manual_toll_count:manual&&Number(row.toll_count)>0?Number(row.toll_count):'',include_mobile:Number(row.mobile_km)>0,include_tolls:manual&&Number(row.toll_count)>0,coverage:row.uninsured?'uninsured':'insured',uninsured:Boolean(row.uninsured),special:Boolean(row.special),gavilan:Boolean(row.gavilan)};state.quoteResult={...row,mode:manual?'manual':'automatic',extra_rate:Number(snapshot.extra_rate??(Number(row.extra_km)?Number(row.extra_price)/Number(row.extra_km):0)),route_segments:[],customer_type:(row.uninsured?'No asegurado':'Asegurado')+(row.gavilan?' · Gavilán':row.special?' · Especial':'')};localStorage.setItem(quoteDraftKey(),JSON.stringify({...state.quoteRestore,mode:state.quoteMode}));state.quoteTab='new';render();toast('Cotización recuperada')}
function quoteTollDetails(r){try{return Array.isArray(r.toll_details)?r.toll_details:JSON.parse(r.toll_details||'[]')}catch{return []}}
