function quoteSummaryText(r){const tolls=quoteTollDetails(r);return [`COTIZACIÓN DE SERVICIO`,r.task_number?`Tarea: ${r.task_number}`:null,`Tipo: ${r.customer_type}`,`Modalidad: ${r.mode==='manual'?'Manual':'Automática'}`,`Traslado origen → destino: ${Number(r.trip_km).toFixed(2)} km`,`Salida de la grúa → origen: ${Number(r.mobile_km).toFixed(2)} km`,`Distancia total considerada: ${Number(r.total_km).toFixed(2)} km`,`Kilómetros incluidos: ${r.included_km} km`,`Kilómetros excedentes: ${r.extra_km} km × ${money(r.extra_rate)}`,`Precio base: ${money(r.base_price)}`,`Adicional por km: ${money(r.extra_price)}`,`Peajes: ${Number(r.toll_count||tolls.length)} · ${money(r.toll_price||0)}${tolls.length?` (${tolls.map(t=>t.name).join(', ')})`:''}`,`PRECIO A INFORMAR: ${money(r.total_price)}`].filter(Boolean).join('\n')}
async function copyQuoteSummary(){if(!state.quoteResult)return;const text=quoteSummaryText(state.quoteResult);try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}toast('Resumen copiado al portapapeles')}
function quoteRulesForm(r){const fields={insured:[['insured_base','Mecánica ligera'],['special_insured_base','ML especial / extracciones'],['locksmith_mvd_insured_base','Cerrajería MVD'],['locksmith_coast_insured_base','Cerrajería C. Costa'],['transfer_insured_base','Traslado'],['transfer_special_insured_base','Traslado MVD especial'],['extra_km_insured_rate','KM extra'],['special_extra_km_insured_rate','KM extra especial'],['toll_insured','Peajes'],['waiting_hour_insured','Horas de espera'],['rescue_hour_insured','Horas de rescate'],['gavilan_insured_base','Gavilán']],uninsured:[['uninsured_base','Mecánica ligera'],['special_uninsured_base','ML especial / extracciones'],['locksmith_mvd_uninsured_base','Cerrajería MVD'],['locksmith_coast_uninsured_base','Cerrajería C. Costa'],['transfer_uninsured_base','Traslado'],['transfer_special_uninsured_base','Traslado MVD especial'],['extra_km_uninsured_rate','KM extra'],['special_extra_km_uninsured_rate','KM extra especial'],['toll_uninsured','Peajes'],['waiting_hour_uninsured','Horas de espera'],['rescue_hour_uninsured','Horas de rescate'],['gavilan_uninsured_base','Gavilán']]};const panel=(tab,title)=>`<section class="quote-cost-panel" data-quote-tab="${tab}" ${state.quoteCostTab===tab?'':'hidden'}><div class="quote-cost-panel-head"><strong>${title}</strong><span>Valores en pesos uruguayos</span></div><div class="quote-cost-grid">${fields[tab].map(([name,label])=>`<div class="quote-cost-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="number" min="0" step="0.01" inputmode="decimal" value="${esc(r[name]??0)}" required></div>`).join('')}</div></section>`;return `<div class="permission-panel quote-rules-panel"><div class="permission-head"><div><h2>Tarifas del cotizador</h2><p>Los cambios se aplican a las próximas cotizaciones y no modifican el historial.</p></div></div><div class="quote-cost-tabs"><button type="button" data-quote-tab="insured" class="quote-cost-tab ${state.quoteCostTab==='insured'?'active':''}" onclick="selectQuoteCostTab('insured')">Costos para asegurados</button><button type="button" data-quote-tab="uninsured" class="quote-cost-tab ${state.quoteCostTab==='uninsured'?'active':''}" onclick="selectQuoteCostTab('uninsured')">Costos para no asegurados</button></div><form id="quote-rules-form"><input type="hidden" name="gavilan_base" value="${esc(r.gavilan_insured_base??r.gavilan_base??0)}"><input type="hidden" name="extra_km_rate" value="${esc(r.extra_km_insured_rate??r.extra_km_rate??0)}"><input type="hidden" name="special_extra_km_rate" value="${esc(r.special_extra_km_insured_rate??r.special_extra_km_rate??0)}"><div class="quote-shared-fields"><div class="quote-cost-field"><label for="included_km">Kilómetros incluidos</label><input id="included_km" name="included_km" type="number" min="0" step="0.01" inputmode="decimal" value="${esc(r.included_km??0)}" required></div><span>El adicional por kilómetro se toma de la pestaña seleccionada.</span></div>${panel('insured','Costos para asegurados')}${panel('uninsured','Costos para no asegurados')}</form><div class="permission-actions"><button type="button" class="primary" onclick="saveQuoteRules()">Guardar tarifas</button></div></div>`}
