function noticeIsOpen(r){return !['RESUELTO','CANCELADO'].includes(r.status)}
function noticeAge(r){const created=new Date(r.created_at),minutes=Math.max(0,Math.floor((Date.now()-created.getTime())/60000));if(Number.isNaN(minutes))return '—';if(minutes<60)return `${Math.max(1,minutes)} min`;const hours=Math.floor(minutes/60);if(hours<24)return `${hours} h`;return `${Math.floor(hours/24)} d`}
function noticeSort(a,b){if(!noticeIsOpen(a)||!noticeIsOpen(b))return new Date(b.created_at)-new Date(a.created_at);const rank=r=>!r.managed_by?0:r.status==='PENDIENTE'?1:r.managed_by===currentUser?2:r.status==='EN_GESTION'?3:4;return rank(a)-rank(b)||new Date(a.created_at)-new Date(b.created_at)}
function noticeRowClass(r){return [r.status==='PENDIENTE'?'priority':'',noticeIsOpen(r)&&!r.managed_by?'notice-unassigned':'',noticeIsOpen(r)&&r.managed_by===currentUser?'notice-own':'',r.status==='ESPERANDO_RESPUESTA'?'notice-waiting':''].filter(Boolean).join(' ')}
