function showNoticeDuplicate(duplicate,body){window.pendingNoticeBody={...body};window.pendingDuplicate=duplicate;$('#modal-title').textContent='Posible aviso duplicado';$('#entity-form').dataset.type='notice_duplicate';$('#fields').innerHTML=`<div class="field full duplicate-warning"><strong>${esc(duplicate.duplicate_reason)}</strong><p>Ya hay un aviso abierto con datos coincidentes. Revisalo antes de crear otro.</p><dl><div><dt>Tarea</dt><dd>${esc(duplicate.task_number||'Sin tarea')}</dd></div><div><dt>Teléfono</dt><dd>${esc(duplicate.phone||'—')}</dd></div><div><dt>Motivo</dt><dd>${esc(duplicate.notice_type)}</dd></div><div><dt>Responsable</dt><dd>${esc(duplicate.managed_by||'Sin responsable')}</dd></div><div><dt>Estado</dt><dd>${esc(statusLabel(duplicate.status))}</dd></div></dl><button type="button" class="row-action" onclick="focusExistingNotice(${duplicate.id})">Ver aviso existente</button><small>Si se trata de otro caso, presioná Guardar para crearlo de todos modos.</small></div>`}
