function noticeActions(r){const actions=[];if(!r.managed_by&&can('notices.assign')&&can('notices.change_status'))actions.push(`<button class="row-action" onclick="manageNotice(${r.id})">Gestionar</button>`);if(can('notices.assign'))actions.push(`<button class="row-action" onclick="openNoticeAssignment(${r.id})">${r.managed_by?'Reasignar':'Asignar'}</button>`);if(can('notices.comment'))actions.push(`<button class="row-action comment-button" aria-label="Agregar comentario" onclick="openNoticeComment(${r.id})">✎</button>`);actions.push(`<button class="row-action" onclick="openNoticeHistory(${r.id})">Historial</button>`);return `<div class="action-cluster">${actions.join('')}</div>`}
function noticeStatusControl(r){const canChange=can('notices.change_status'),canClose=can('notices.close');if(!canChange&&!canClose)return badge(r.status);const options=[['PENDIENTE','Pendiente'],['EN_GESTION','En gestión'],['ESPERANDO_RESPUESTA','Esperando respuesta'],['RESUELTO','Resuelto'],['CANCELADO','Cancelado']].filter(([value])=>['RESUELTO','CANCELADO'].includes(value)?canClose:canChange);return `<details class="status-dropdown"><summary class="status-chip ${esc(r.status)}">${esc(statusLabel(r.status))}</summary><div class="status-options">${options.map(([value,label])=>`<button class="status-option ${value}" onclick="changeNoticeStatus(${r.id},'${value}')">${label}</button>`).join('')}</div></details>`}
async function assignNotice(id){await api(`/api/notices/${id}/status`,{method:'PATCH',body:JSON.stringify({managed_by:currentUser})});toast(`Aviso asignado a ${currentUser}`);render()}
