function normalizedTransferStatus(status){return ({PENDIENTE:'SIN_ASIGNAR',CONFIRMADO:'ASIGNADO',COMPLETADO:'FINALIZADO'}[status]||status||'SIN_ASIGNAR')}
const transferTransitions={SIN_ASIGNAR:['ASIGNADO','CANCELADO'],ASIGNADO:['SIN_ASIGNAR','EN_CURSO','CANCELADO'],EN_CURSO:['ASIGNADO','FINALIZADO','CANCELADO'],FINALIZADO:[],CANCELADO:[]};
function transferStatusSelect(r){const current=normalizedTransferStatus(r.status),options=transferTransitions[current]||[];if(!can('transfers.manage')||!options.length)return badge(current);return `<details class="status-dropdown"><summary class="status-chip ${esc(current)}">${esc(statusLabel(current))}</summary><div class="status-options">${options.map(status=>`<button class="status-option ${status}" onclick="openTransferTransition(${r.id},'${status}')">${esc(statusLabel(status))}</button>`).join('')}</div></details>`}
function transferRowClass(r){const t=(r.transfer_type||'').toLowerCase(),status=normalizedTransferStatus(r.status),scheduled=new Date(`${r.scheduled_date}T${String(r.scheduled_time||'23:59').slice(0,5)}`),overdue=['SIN_ASIGNAR','ASIGNADO'].includes(status)&&scheduled<Date.now();return `transfer-row ${overdue?'transfer-overdue ':''}${t.includes('depósito')||t.includes('deposito')?'transfer-deposit':t.includes('directo')?'transfer-direct':t.includes('mercosur')?'transfer-mercosur':'transfer-long'}`}
function transferColumns(){return [['Fecha','scheduled_date'],['Hora',r=>esc(r.scheduled_time?.slice(0,5)||'—')],['Tarea',r=>taskLink(r.task_number)],['Desde','origin'],['Hacia','destination'],['Prestador',r=>esc(r.provider||'Sin asignar')],['Responsable',r=>esc(r.responsible||'Sin asignar')],['Planifica','planner'],['Estado',r=>transferStatusSelect(r)],['Acciones',r=>transferActions(r)]]}
function transferActions(r){const terminal=['FINALIZADO','CANCELADO'].includes(normalizedTransferStatus(r.status)),actions=[`<button class="row-action" onclick="openTransferHistory(${r.id})">Historial</button>`];if(can('transfers.manage')&&!terminal)actions.unshift(`<button class="row-action edit-transfer" onclick="openEditTransfer(${r.id})">✎ Editar</button>`);if(can('transfers.manage'))actions.push(`<details class="more-menu"><summary aria-label="Más opciones">•••</summary><div class="more-menu-pop"><button onclick="duplicateTransfer(${r.id})">Duplicar como nuevo</button>${terminal?'':`<button class="delete-option" onclick="openTransferTransition(${r.id},'CANCELADO')">Cancelar programado</button>`}</div></details>`);return `<div class="action-cluster">${actions.join('')}</div>`}
function groupedTransfers(rows){if(!rows.length)return `<div class="panel empty">No hay programados para los filtros seleccionados.</div>`;const groups=[['Traslados largos',r=>!/(depósito|deposito|directo|mercosur)/i.test(r.transfer_type||'')],['Traslados a depósito',r=>/(depósito|deposito)/i.test(r.transfer_type||'')],['Traslados directos',r=>/directo/i.test(r.transfer_type||'')],['Mercosur',r=>/mercosur/i.test(r.transfer_type||'')]];return groups.map(([name,test])=>{const items=rows.filter(test);return items.length?`<section class="transfer-group"><div class="group-heading"><div><h2>${name}</h2><span>${items.length} ${items.length===1?'programado':'programados'}</span></div></div>${table(transferColumns(),items,transferRowClass)}</section>`:''}).join('')}
function setTransferView(view){state.transferView=view;render()}
function transferFilterParams(){const params=new URLSearchParams();if(state.transferFrom)params.set('date_from',state.transferFrom);if(state.transferTo)params.set('date_to',state.transferTo);const viewStatus=state.transferView==='active'?'ACTIVE':state.transferView==='finished'?'FINALIZADO':state.transferView==='cancelled'?'CANCELADO':'';if(state.transferStatus||viewStatus)params.set('status',state.transferStatus||viewStatus);if(state.transferType)params.set('transfer_type',state.transferType);if(state.transferProvider)params.set('provider',state.transferProvider);if(state.transferResponsible)params.set('responsible',state.transferResponsible);if(state.transferTask)params.set('task',state.transferTask);if(state.transferSearch)params.set('q',state.transferSearch);return params}
