async function saveTransfer(endpoint,method,body){try{return await api(endpoint,{method,body:JSON.stringify(body)})}catch(error){const duplicate=error.status===409&&error.payload?.detail?.duplicate;if(!duplicate||!confirm(`Ya existe un programado coincidente para la tarea ${duplicate.task_number}. ¿Guardar igualmente como un caso independiente?`))throw error;return api(endpoint,{method,body:JSON.stringify({...body,allow_duplicate:true})})}}
function duplicateTransfer(id){const r=window.transferCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent='Duplicar programado';$('#entity-form').dataset.type='transfer_duplicate';$('#entity-form').dataset.transferId=id;$('#fields').innerHTML=`<div class="field full"><label>Número de tarea para la copia</label><input name="task_number" value="${esc(r.task_number)}" maxlength="120" required></div><div class="field full operation-summary"><strong>${esc(r.transfer_type)}</strong><span>${esc(r.scheduled_date)}${r.scheduled_time?` · ${esc(r.scheduled_time.slice(0,5))}`:''}</span><small>${esc(r.origin)} → ${esc(r.destination)}</small></div><div class="field full"><small>La copia se guardará Sin asignar, sin prestador ni responsable. El registro original no se modifica.</small></div>`;$('#modal').showModal();queueMicrotask(()=>{$('#save').textContent='Crear copia'})}
async function openTransferTransition(id,status){const r=window.transferCache.find(x=>x.id===id);if(!r)return;try{const people=status==='ASIGNADO'?await api('/api/transfers/responsibles'):[];$('#modal-title').textContent=`${statusLabel(status)} · tarea ${esc(r.task_number)}`;$('#entity-form').dataset.type='transfer_status';$('#entity-form').dataset.transferId=id;const assignment=status==='ASIGNADO'?`<div class="field"><label>Prestador / Auxiliador</label><input name="provider" value="${esc(r.provider||'')}" maxlength="200" required></div><div class="field"><label>Responsable interno</label><select name="responsible" required><option value="">Seleccionar</option>${people.map(person=>`<option value="${esc(person.display_name)}" ${person.display_name===r.responsible?'selected':''}>${esc(person.display_name)} · ${esc(person.role_name)}</option>`).join('')}</select></div>`:'';const note=['FINALIZADO','CANCELADO'].includes(status)?`<div class="field full"><label>${status==='FINALIZADO'?'Resultado del traslado':'Motivo de la cancelación'}</label><textarea name="note" minlength="2" maxlength="1000" rows="5" required></textarea><small>La observación quedará registrada en el historial.</small></div>`:'';$('#fields').innerHTML=`<input type="hidden" name="status" value="${status}">${assignment}${note}<div class="field full"><small>${status==='EN_CURSO'?'Confirmá el inicio cuando el servicio haya comenzado.':status==='SIN_ASIGNAR'?'El programado volverá a la cola sin responsable.':'El cambio quedará asociado a tu usuario, fecha y hora.'}</small></div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
async function openTransferHistory(id){const r=window.transferCache.find(x=>x.id===id);if(!r)return;try{const events=await api(`/api/transfers/${id}/events`);$('#modal-title').textContent=`Historial del programado · tarea ${esc(r.task_number)}`;$('#entity-form').dataset.type='transfer_history';$('#save').textContent='Cerrar';$('#fields').innerHTML=`<div class="field full notice-timeline">${events.length?events.map(event=>`<article><i></i><div><div class="notice-event-head"><strong>${esc(event.event_type==='CREADO'?'Programado creado':event.event_type==='EDITADO'?'Datos editados':'Estado actualizado')}</strong><time>${esc(fmt(event.created_at))}</time></div><span>${esc(event.actor)}</span>${event.previous_status||event.new_status?`<p class="notice-event-change">${esc(statusLabel(event.previous_status||'Sin estado'))} → ${esc(statusLabel(event.new_status))}</p>`:''}${event.note?`<p>${esc(event.note)}</p>`:''}</div></article>`).join(''):'<div class="empty">No hay movimientos registrados.</div>'}</div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
const forms={
 notice:[['task_number','Número de tarea (opcional)'],['phone','Teléfono del cliente (opcional)'],['notice_type','Motivo del aviso'],['audience','¿Para quién es?','select',['TODOS','TELEFONISTAS','PLANIFICADORES']],['detail','Detalle del aviso','textarea']],
 delay:[['service','Prestación afectada','select',['TODAS','GRÚA','ML','SINIESTROS']],['department','Departamento','select',['ARTIGAS','CANELONES','CERRO LARGO','COLONIA','DURAZNO','FLORES','FLORIDA','LAVALLEJA','MALDONADO','MONTEVIDEO','PAYSANDÚ','RÍO NEGRO','RIVERA','ROCHA','SALTO','SAN JOSÉ','SORIANO','TACUAREMBÓ','TREINTA Y TRES']],['zone','Zona afectada dentro del departamento','textarea'],['message','¿Qué se informa al cliente?','select',['No confirmar tiempos','Margen de','A confirmar']],['minutes','Margen en minutos (solo si corresponde)','number'],['review_minutes','Volver a verificar en','select',['60','120','240','480']]],
 transfer:[['task_number','Tarea'],['transfer_type','Tipo','select',['Traslado Largo','Traslado Depósito','Traslado Directo','Mercosur']],['scheduled_date','Fecha','date'],['scheduled_time','Hora','time'],['origin','Desde'],['destination','Hacia'],['provider','Prestador / Auxiliador'],['comments','Comentarios','textarea']]
};
function openForm(type){$('#modal-title').textContent={notice:'Registrar nuevo aviso',delay:'Registrar demora vigente',transfer:'Nuevo traslado programado'}[type];$('#entity-form').dataset.type=type;if(type==='notice'){$('#fields').innerHTML=`<div class="field"><label>Número de tarea <small>Opcional</small></label><input name="task_number" maxlength="120" autocomplete="off"></div><div class="field"><label>Teléfono del cliente <small>Opcional</small></label><input name="phone" maxlength="80" inputmode="tel" autocomplete="off"></div><div class="field"><label>Motivo del aviso</label><input name="notice_type" minlength="2" maxlength="120" placeholder="Ej.: reclamo, coordinación o consulta" required></div><div class="field"><label>Dirigido a</label><select name="audience"><option value="TODOS">Todo el equipo</option><option value="TELEFONISTAS">Telefonistas</option><option value="PLANIFICADORES">Planificadores</option></select></div><div class="field full"><label>¿Qué necesita saber o hacer el equipo?</label><textarea name="detail" minlength="2" maxlength="4000" rows="6" placeholder="Describí el pendiente, la información relevante y el próximo paso esperado" required></textarea></div>${can('notices.assign')?`<label class="field full notice-self-assign"><input name="managed_by" value="${esc(currentUser)}" type="checkbox"><span><strong>Asignármelo al guardar</strong><small>Quedará visible en tu cola de trabajo.</small></span></label>`:''}<div class="field full"><small>La fecha, hora y usuario (${esc(currentUser)}) se registran automáticamente. Antes de guardar se revisarán coincidencias abiertas.</small></div>`}else{$('#fields').innerHTML=forms[type].map(([n,l,k='text',opts])=>`<div class="field ${k==='textarea'?'full':''}"><label>${l}</label>${k==='select'?`<select name="${n}">${opts.map(o=>`<option>${esc(o)}</option>`).join('')}</select>`:k==='textarea'?`<textarea name="${n}"></textarea>`:`<input name="${n}" type="${k}">`}</div>`).join('')+`<div class="field full"><small>La fecha, hora y usuario (${esc(currentUser)}) se registran automáticamente.</small></div>`}$('#modal').showModal()}
function openStandardForm(id=null){const row=(window.standardCache||[]).find(item=>item.id===id)||{},departments=[...DELAY_DEPARTMENTS,'INTERIOR'],services=['GRÚA','ML','SINIESTROS'],statuses=['CONFIRMADO','PROVISIONAL','SIN_REFERENCIA'],zones=window.zoneCache||[],proposal=!id&&!can('settings.manage');$('#modal-title').textContent=id?'Editar referencia habitual':proposal?'Proponer referencia habitual':'Nueva referencia habitual';$('#entity-form').dataset.type=id?'standard_edit':proposal?'standard_proposal':'standard';$('#entity-form').dataset.standardId=id||'';$('#fields').innerHTML=`<div class="field"><label>Departamento</label><select name="department">${departments.map(value=>`<option ${value===(row.department||state.selectedStandardDept)?'selected':''}>${esc(value)}</option>`).join('')}</select></div><div class="field"><label>Prestación</label><select name="service">${services.map(value=>`<option ${value===row.service?'selected':''}>${esc(value)}</option>`).join('')}</select></div><div class="field full"><label>Zona de cobertura</label><input name="zone" list="standard-form-zones" value="${esc(row.zone||'')}" required><datalist id="standard-form-zones">${zones.map(zone=>`<option value="${esc(zone.name)}"></option>`).join('')}</datalist></div><div class="field"><label>Tiempo mínimo (minutos)</label><input name="minutes_min" type="number" min="1" max="1440" value="${esc(row.minutes_min||'')}"></div><div class="field"><label>Tiempo máximo (minutos)</label><input name="minutes_max" type="number" min="1" max="1440" value="${esc(row.minutes_max||'')}"></div><div class="field"><label>Estado</label><select name="status">${statuses.map(value=>`<option value="${value}" ${value===(row.status||'PROVISIONAL')?'selected':''}>${esc(standardStatusLabel(value))}</option>`).join('')}</select></div><div class="field"><label>Vigente desde</label><input name="effective_from" type="date" value="${esc(String(row.effective_from||isoDate(new Date())).slice(0,10))}"></div><div class="field"><label>Responsable</label><input name="owner" value="${esc(row.owner||'Supervisión')}" required></div><div class="field"><label>Ciclo de revisión (días)</label><input name="review_interval_days" type="number" min="1" max="365" value="${esc(row.review_interval_days||90)}" required></div><div class="field"><label>Próxima revisión</label><input name="review_due_at" type="date" value="${esc(String(row.review_due_at||'').slice(0,10))}"></div><div class="field full"><label>Fuente de la referencia</label><input name="source" value="${esc(row.source||'')}" placeholder="Ej.: acuerdo operativo, prestador o medición"></div><div class="field full"><label>Nota para el operador</label><textarea name="note">${esc(row.note||'')}</textarea></div><div class="field full"><small>${proposal?'La propuesta quedará pendiente de aprobación y no será comunicable hasta que Supervisión la valide.':'Confirmado exige un tiempo y una fuente. Sin referencia no admite minutos. Si no indicás revisión, se calcula desde el ciclo.'}</small></div>`;$('#modal').showModal()}
function openZoneCoverageForm(id=null){const zone=(window.zoneCache||[]).find(item=>item.id===id)||{},services=['GRÚA','ML','SINIESTROS'],selected=zone.expected_services||[];$('#modal-title').textContent=zone.id?'Configurar cobertura de zona':'Definir cobertura esperada';$('#entity-form').dataset.type='zone_coverage';$('#fields').innerHTML=`<div class="field"><label>Departamento</label><select name="department">${[...DELAY_DEPARTMENTS,'INTERIOR'].map(value=>`<option ${value===(zone.department||state.selectedStandardDept)?'selected':''}>${esc(value)}</option>`).join('')}</select></div><div class="field"><label>Zona</label><input name="name" value="${esc(zone.name||'')}" required></div><div class="field full"><label>Prestaciones que deberían tener referencia</label><div class="coverage-checks">${services.map(service=>`<label><input type="checkbox" name="expected_services" value="${esc(service)}" ${selected.includes(service)?'checked':''}> ${esc(service)}</label>`).join('')}</div></div><div class="field full"><label>Responsable de cobertura</label><input name="owner" value="${esc(zone.owner||'Supervisión')}" required></div><div class="field full"><small>Solo estas prestaciones generarán alertas de cobertura para la zona.</small></div>`;$('#modal').showModal()}
$('#entity-form').addEventListener('submit',async event=>{const type=event.currentTarget.dataset.type;if(!['standard_proposal','zone_coverage'].includes(type))return;event.preventDefault();event.stopImmediatePropagation();const form=new FormData(event.currentTarget),body=Object.fromEntries(form);try{if(type==='standard_proposal'){for(const key of ['minutes_min','minutes_max'])body[key]=body[key]?Number(body[key]):null;body.review_interval_days=Number(body.review_interval_days);body.review_due_at=body.review_due_at||null;body.effective_from=body.effective_from||null;body.active=true;await api('/api/standards/proposals',{method:'POST',body:JSON.stringify(body)});toast('Propuesta enviada a Supervisión')}else{body.expected_services=form.getAll('expected_services');await api('/api/settings/zones',{method:'POST',body:JSON.stringify(body)});toast('Cobertura esperada actualizada')}$('#modal').close();render()}catch(error){toast(error.message)}},true);
$('#entity-form').addEventListener('submit',async event=>{const type=event.currentTarget.dataset.type;if(!['delay_verify','delay_normalize','standard_decision','transfer_duplicate'].includes(type))return;event.preventDefault();event.stopImmediatePropagation();const body=Object.fromEntries(new FormData(event.currentTarget));try{if(type==='delay_verify'){body.review_minutes=Number(body.review_minutes);await api(`/api/delays/${event.currentTarget.dataset.delayId}/verify`,{method:'PATCH',body:JSON.stringify(body)});toast('Vigencia renovada y registrada')}else if(type==='delay_normalize'){await api(`/api/delays/${event.currentTarget.dataset.delayId}/normalize`,{method:'PATCH',body:JSON.stringify({status:'NORMALIZADO',resolution_note:body.resolution_note})});toast('Demora normalizada con evidencia de cierre')}else if(type==='standard_decision'){const decision=event.currentTarget.dataset.decision;await api(`/api/settings/standards/${event.currentTarget.dataset.standardId}/decision`,{method:'PATCH',body:JSON.stringify({decision,note:body.note})});toast(decision==='APPROVED'?'Referencia aprobada':'Propuesta rechazada')}else{const original=window.transferCache.find(item=>item.id===Number(event.currentTarget.dataset.transferId));if(!original)throw new Error('No se encontró el programado original');await saveTransfer('/api/transfers','POST',{task_number:body.task_number.trim(),transfer_type:original.transfer_type,scheduled_date:original.scheduled_date,scheduled_time:original.scheduled_time,origin:original.origin,destination:original.destination,provider:null,responsible:null,comments:original.comments});toast('Programado duplicado como Sin asignar')}$('#modal').close();render()}catch(error){toast(error.message)}},true);
$('#entity-form').addEventListener('submit',event=>{if(!['delay_history','standard_history','transfer_history'].includes(event.currentTarget.dataset.type))return;event.preventDefault();event.stopImmediatePropagation();$('#modal').close()},true);
$('#entity-form').addEventListener('submit',async event=>{const type=event.currentTarget.dataset.type;if(type==='notice_history'){event.preventDefault();event.stopImmediatePropagation();$('#modal').close();return}if(type==='notice_close'){event.preventDefault();event.stopImmediatePropagation();const r=window.noticeCache.find(item=>item.id===Number(event.currentTarget.dataset.noticeId)),body=Object.fromEntries(new FormData(event.currentTarget));if(!r)return;try{await api(`/api/notices/${r.id}/status`,{method:'PATCH',body:JSON.stringify(body)});$('#modal').close();toast(body.status==='RESUELTO'?'Aviso resuelto':'Aviso cancelado');render()}catch(error){toast(error.message)}}},true);
$('#entity-form').addEventListener('submit',async event=>{const type=event.currentTarget.dataset.type;if(!['transfer','transfer_edit','transfer_status'].includes(type))return;event.preventDefault();event.stopImmediatePropagation();const body=Object.fromEntries(new FormData(event.currentTarget));Object.keys(body).forEach(key=>{if(body[key]==='')body[key]=null});try{const id=event.currentTarget.dataset.transferId;if(type==='transfer_status')await api(`/api/transfers/${id}/status`,{method:'PATCH',body:JSON.stringify(body)});else await saveTransfer(type==='transfer_edit'?`/api/transfers/${id}`:'/api/transfers',type==='transfer_edit'?'PATCH':'POST',body);$('#modal').close();toast(type==='transfer_status'?`Estado: ${statusLabel(body.status)}`:type==='transfer_edit'?'Programado actualizado':'Programado creado');render()}catch(error){toast(error.message)}},true);
$('#entity-form').addEventListener('submit',async e=>{e.preventDefault();const type=e.target.dataset.type,form=new FormData(e.target);try{if(type==='role'){await api(`/api/roles/${e.target.dataset.roleId}/permissions`,{method:'PATCH',body:JSON.stringify({permissions:form.getAll('permissions')})});$('#modal').close();toast('Permisos actualizados');return render()}const body=Object.fromEntries(form);if(type==='notice_duplicate'){const pending=window.pendingNoticeBody;if(!pending)throw new Error('No se encontró el aviso pendiente de confirmación');pending.allow_duplicate=true;await api('/api/notices',{method:'POST',body:JSON.stringify(pending)});window.pendingNoticeBody=null;window.pendingDuplicate=null;$('#modal').close();toast('Aviso creado como caso independiente');return render()}if(type==='role_create'){const created=await api('/api/settings/roles',{method:'POST',body:JSON.stringify(body)});state.selectedRole=created.id;$('#modal').close();toast('Rol creado');return render()}if(type==='user'){body.role_id=Number(body.role_id);await api('/api/settings/users',{method:'POST',body:JSON.stringify(body)});$('#modal').close();toast('Usuario creado');return render()}if(type==='user_edit'){body.role_id=Number(body.role_id);body.active=form.has('active');await api(`/api/users/${e.target.dataset.userId}`,{method:'PATCH',body:JSON.stringify(body)});$('#modal').close();toast('Usuario actualizado');return render()}if(type==='schedule'||type==='schedule_edit'){body.user_id=Number(body.user_id);body.start_time=body.start_time||null;body.end_time=body.end_time||null;body.notes=body.notes||null;const endpoint=type==='schedule_edit'?`/api/schedules/${e.target.dataset.scheduleId}`:'/api/schedules';await api(endpoint,{method:type==='schedule_edit'?'PATCH':'POST',body:JSON.stringify(body)});$('#modal').close();toast(type==='schedule_edit'?'Horario actualizado':'Horario configurado');return render()}if(type==='notice_assignment'){const r=window.noticeCache.find(x=>x.id===Number(e.target.dataset.noticeId));await api(`/api/notices/${r.id}/status`,{method:'PATCH',body:JSON.stringify({managed_by:body.managed_by||null})});$('#modal').close();toast(body.managed_by?`Aviso asignado a ${body.managed_by}`:'Aviso sin responsable');return render()}if(type==='notice_comment'){const r=window.noticeCache.find(x=>x.id===Number(e.target.dataset.noticeId));await api(`/api/notices/${r.id}/status`,{method:'PATCH',body:JSON.stringify({status:r.status,actor:currentUser,managed_by:r.managed_by||null,comments:body.comments||null})});$('#modal').close();toast('Comentario guardado');return render()}Object.keys(body).forEach(k=>{if(body[k]==='')body[k]=null});if(type==='standard'||type==='standard_edit'){for(const key of ['minutes_min','minutes_max'])body[key]=body[key]===null?null:Number(body[key]);body.active=true;const id=e.target.dataset.standardId,endpoint=id?`/api/settings/standards/${id}`:'/api/settings/standards';await api(endpoint,{method:id?'PATCH':'POST',body:JSON.stringify(body)});$('#modal').close();toast(id?'Referencia actualizada':'Referencia creada');return render()}if(type==='transfer_edit'){await api(`/api/transfers/${e.target.dataset.transferId}`,{method:'PATCH',body:JSON.stringify(body)});$('#modal').close();toast('Programado actualizado');return render()}if(body.minutes)body.minutes=Number(body.minutes);if(type==='notice'){body.communicated_by=currentUser;body.status='PENDIENTE';const duplicate=await findNoticeDuplicate(body);if(duplicate){showNoticeDuplicate(duplicate,body);return}}if(type==='delay'){body.agent=currentUser;body.status='VIGENTE'}if(type==='transfer'){body.planner=currentUser;body.status='SIN_ASIGNAR'}const endpoint={notice:'notices',delay:'delays',transfer:'transfers'}[type];await api(`/api/${endpoint}`,{method:'POST',body:JSON.stringify(body)});$('#modal').close();toast('Registro guardado correctamente');render()}catch(x){toast(x.message)}});
async function manageNotice(id){await api(`/api/notices/${id}/status`,{method:'PATCH',body:JSON.stringify({status:'EN_GESTION',managed_by:currentUser})});toast(`Aviso asignado a ${currentUser}`);render()}
function openNoticeClosure(id,status='RESUELTO'){const r=window.noticeCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent=`Cerrar aviso${r.task_number?' · Tarea '+r.task_number:''}`;$('#entity-form').dataset.type='notice_close';$('#entity-form').dataset.noticeId=id;$('#fields').innerHTML=`<div class="field"><label>Resultado</label><select name="status"><option value="RESUELTO" ${status==='RESUELTO'?'selected':''}>Resuelto</option><option value="CANCELADO" ${status==='CANCELADO'?'selected':''}>Cancelado</option></select></div><div class="field full"><label>Resultado o motivo del cierre</label><textarea name="comments" minlength="2" maxlength="4000" rows="6" placeholder="Indicá qué se resolvió o por qué se cancela" required></textarea><small>Este texto quedará en el historial junto con tu nombre, fecha y hora.</small></div>`;$('#modal').showModal()}
async function openNoticeAssignment(id){const r=window.noticeCache.find(x=>x.id===id);if(!r)return;try{const people=await api('/api/notices/assignees');$('#modal-title').textContent=`Asignar aviso${r.task_number?' · Tarea '+r.task_number:''}`;$('#entity-form').dataset.type='notice_assignment';$('#entity-form').dataset.noticeId=id;$('#fields').innerHTML=`<div class="field full"><label>Responsable</label><select name="managed_by"><option value="">Sin responsable</option>${people.map(person=>`<option value="${esc(person.display_name)}" ${person.display_name===r.managed_by?'selected':''}>${esc(person.display_name)} · ${esc(person.role_name)}</option>`).join('')}</select><small>Solo aparecen usuarios activos cuyo rol permite consultar Avisos.</small></div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
function openNoticeComment(id){const r=window.noticeCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent=`Comentario de gestión${r.task_number?' · Tarea '+r.task_number:''}`;$('#entity-form').dataset.type='notice_comment';$('#entity-form').dataset.noticeId=id;$('#fields').innerHTML=`<div class="field full"><label>Comentario</label><textarea name="comments" rows="7" placeholder="Escribí el seguimiento o resultado de la gestión...">${esc(r.comments||'')}</textarea></div>`;$('#modal').showModal()}
function noticeEventTitle(event){return {CREADO:'Aviso creado',ESTADO:'Estado actualizado',ASIGNACION:'Responsable actualizado',COMENTARIO:'Comentario de seguimiento',AVISO_ACTUALIZADO:'Aviso actualizado',CAMBIO_ESTADO:'Estado actualizado'}[event.event_type]||statusLabel(event.event_type)}
function noticeEventChange(event){if(event.event_type==='ESTADO')return `${esc(statusLabel(event.previous_value||'Sin estado'))} → ${esc(statusLabel(event.new_value))}`;if(event.event_type==='ASIGNACION')return `${esc(event.previous_value||'Sin responsable')} → ${esc(event.new_value||'Sin responsable')}`;if(event.new_value)return esc(statusLabel(event.new_value));return ''}
async function openNoticeHistory(id){const r=window.noticeCache.find(x=>x.id===id);if(!r)return;try{const events=await api(`/api/notices/${id}/history`);$('#modal-title').textContent=`Historial del aviso${r.task_number?' · Tarea '+r.task_number:''}`;$('#entity-form').dataset.type='notice_history';$('#entity-form').dataset.noticeId=id;$('#save').textContent='Cerrar';$('#fields').innerHTML=`<div class="field full notice-timeline">${events.length?events.map(event=>`<article><i></i><div><div class="notice-event-head"><strong>${esc(noticeEventTitle(event))}</strong><time>${esc(fmt(event.created_at))}</time></div><span>${esc(event.actor)}</span>${noticeEventChange(event)?`<p class="notice-event-change">${noticeEventChange(event)}</p>`:''}${event.comment?`<p>${esc(event.comment)}</p>`:''}${event.detail?`<small>${esc(event.detail)}</small>`:''}</div></article>`).join(''):'<div class="empty">No hay movimientos registrados.</div>'}</div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
$('#modal').addEventListener('close',()=>{$('#save').textContent='Guardar'});
function normalizeDelay(id){const row=(window.delayCache||[]).find(item=>item.id===id);$('#modal-title').textContent='Confirmar normalización';$('#entity-form').dataset.type='delay_normalize';$('#entity-form').dataset.delayId=id;$('#fields').innerHTML=`${row?`<div class="field full operation-summary"><strong>${esc(row.department)} · ${esc(row.zone)}</strong><span>${esc(row.service)}</span><small>${esc(row.message)}</small></div>`:''}<div class="field full"><label>¿Cómo se confirmó la normalización?</label><textarea name="resolution_note" minlength="2" maxlength="1000" rows="5" placeholder="Indicá la fuente o comprobación realizada" required></textarea><small>La evidencia quedará asociada a tu usuario, fecha y hora.</small></div>`;$('#modal').showModal();queueMicrotask(()=>{$('#save').textContent='Confirmar cierre'})}
function verifyDelay(id){const row=(window.delayCache||[]).find(item=>item.id===id);$('#modal-title').textContent='Renovar control de vigencia';$('#entity-form').dataset.type='delay_verify';$('#entity-form').dataset.delayId=id;$('#fields').innerHTML=`${row?`<div class="field full operation-summary"><strong>${esc(row.department)} · ${esc(row.zone)}</strong><span>${esc(row.service)}</span><small>${esc(row.message)}</small></div>`:''}<div class="field full"><label>¿Cómo se verificó que continúa vigente?</label><textarea name="verification_note" minlength="2" maxlength="1000" rows="4" required></textarea></div><div class="field"><label>Volver a revisar en</label><select name="review_minutes" required><option value="60">1 hora</option><option value="120" selected>2 horas</option><option value="240">4 horas</option><option value="480">8 horas</option><option value="1440">24 horas</option></select></div>`;$('#modal').showModal();queueMicrotask(()=>{$('#save').textContent='Renovar vigencia'})}
async function openDelayHistory(id){try{const events=await api(`/api/delays/${id}/events`);$('#modal-title').textContent='Historial de la demora';$('#entity-form').dataset.type='delay_history';$('#save').textContent='Cerrar';$('#fields').innerHTML=`<div class="field full notice-timeline">${events.length?events.map(event=>`<article><i></i><div><div class="notice-event-head"><strong>${esc({CREATED:'Demora registrada',CREADO:'Demora registrada',VERIFICADO:'Vigencia confirmada',NORMALIZADO:'Demora normalizada'}[event.event_type]||statusLabel(event.event_type))}</strong><time>${esc(fmt(event.created_at))}</time></div><span>${esc(event.actor)}</span>${event.note?`<p>${esc(event.note)}</p>`:''}${event.review_due_at?`<small>Próxima revisión: ${esc(fmt(event.review_due_at))}</small>`:''}</div></article>`).join(''):'<div class="empty">No hay eventos registrados.</div>'}</div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
async function openStandardHistory(id){try{const versions=await api(`/api/settings/standards/${id}/versions`);$('#modal-title').textContent='Historial de la referencia';$('#entity-form').dataset.type='standard_history';$('#save').textContent='Cerrar';$('#fields').innerHTML=`<div class="field full notice-timeline">${versions.length?versions.map(version=>`<article><i></i><div><div class="notice-event-head"><strong>Versión ${version.version} · ${esc(statusLabel(version.action))}</strong><time>${esc(fmt(version.created_at))}</time></div><span>${esc(version.actor)}</span>${version.reason?`<p>${esc(version.reason)}</p>`:''}<small>${esc(version.snapshot.department)} · ${esc(version.snapshot.service)} · ${esc(version.snapshot.zone)} · ${esc(standardTime(version.snapshot))}</small></div></article>`).join(''):'<div class="empty">La referencia todavía no tiene versiones registradas.</div>'}</div>`;$('#modal').showModal()}catch(error){toast(error.message)}}
function decideStandard(id,decision){const row=(window.standardCache||[]).find(item=>item.id===id);$('#modal-title').textContent=decision==='APPROVED'?'Aprobar referencia propuesta':'Rechazar referencia propuesta';$('#entity-form').dataset.type='standard_decision';$('#entity-form').dataset.standardId=id;$('#entity-form').dataset.decision=decision;$('#fields').innerHTML=`${row?`<div class="field full operation-summary"><strong>${esc(row.department)} · ${esc(row.zone)}</strong><span>${esc(row.service)} · ${esc(standardTime(row))}</span><small>${esc(row.source||'Sin fuente informada')}</small></div>`:''}<div class="field full"><label>${decision==='APPROVED'?'Fundamento de la aprobación':'Motivo del rechazo'}</label><textarea name="note" minlength="2" maxlength="1000" rows="5" required></textarea><small>La decisión y su fundamento quedarán en el historial.</small></div>`;$('#modal').showModal();queueMicrotask(()=>{$('#save').textContent=decision==='APPROVED'?'Aprobar referencia':'Rechazar propuesta'})}
function permissionHint(key){const hints={'dashboard.view':'Acceso al panel de indicadores','delays.view':'Puede consultar demoras activas e históricas','delays.create':'Puede informar una nueva afectación','delays.normalize':'Puede retirar una demora de la vista activa','notices.view':'Puede consultar avisos del equipo','notices.create':'Puede dejar un nuevo aviso','notices.comment':'Puede agregar comentarios de seguimiento','notices.assign':'Puede asignar avisos a una persona','notices.change_status':'Puede mover avisos entre estados abiertos','notices.close':'Puede resolver o cancelar avisos','transfers.view':'Puede consultar servicios programados','transfers.create':'Puede registrar servicios programados','transfers.manage':'Puede editar programados y cambiar su estado','schedules.view':'Puede consultar horarios por semana y persona','schedules.manage':'Puede crear, editar y eliminar horarios','quotes.view':'Puede consultar el cotizador y su historial','quotes.create':'Puede calcular y guardar nuevas cotizaciones','standards.view':'Puede consultar referencias de arribo','audit.view':'Puede consultar el registro de auditoría','settings.manage':'Puede cambiar usuarios, roles y permisos'};return esc(hints[key]||'Permiso del sistema')}
function selectSettingsTab(tab){state.settingsTab=tab;render()}
function selectQuoteCostTab(tab){state.quoteCostTab=tab;const panels=document.querySelectorAll('.quote-cost-panel');if(!panels.length){render();return}document.querySelectorAll('.quote-cost-tab').forEach(button=>button.classList.toggle('active',button.dataset.quoteTab===tab));panels.forEach(panel=>{panel.hidden=panel.dataset.quoteTab!==tab})}
function selectRole(id){state.selectedRole=id;render()}
async function saveRolePermissions(id){const permissions=[...document.querySelectorAll('[data-role-permission]:checked')].map(x=>x.value);await api(`/api/roles/${id}/permissions`,{method:'PATCH',body:JSON.stringify({permissions})});toast('Permisos del rol actualizados');authUser=await api('/api/auth/me');render()}
function openUserForm(){const roles=window.roleCache||[];$('#modal-title').textContent='Crear usuario corporativo';$('#entity-form').dataset.type='user';$('#fields').innerHTML=`<div class="field"><label>Nombre visible</label><input name="display_name" required></div><div class="field"><label>Correo corporativo</label><input name="email" type="email" placeholder="nombre@portoservicios.com.uy" pattern=".+@portoservicios\\.com\\.uy" required></div><div class="field"><label>Usuario alternativo (opcional)</label><input name="username" placeholder="Se usará la parte anterior al @"></div>${passwordField('password','Contraseña alternativa (opcional)','Mínimo 12 caracteres')}<div class="field"><label>Rol</label><select name="role_id">${roles.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></div><div class="field full"><small>El usuario puede ingresar con su correo o usuario y esta contraseña local.</small></div>`;$('#modal').showModal()}
function openRoleForm(){$('#modal-title').textContent='Crear rol personalizado';$('#entity-form').dataset.type='role_create';$('#fields').innerHTML=`<div class="field full"><label>Nombre del rol</label><input name="name" required placeholder="Ej.: Coordinador nocturno"></div><div class="field full"><label>Descripción (opcional)</label><textarea name="description" placeholder="Responsabilidad principal del rol"></textarea></div><div class="field full"><small>El rol se creará sin permisos. Después podrás habilitarlos desde esta misma pestaña.</small></div>`;$('#modal').showModal()}
function openEditTransfer(id){const r=window.transferCache.find(x=>x.id===id);if(!r)return;$('#modal-title').textContent=`Editar programado ${esc(r.task_number)}`;$('#entity-form').dataset.type='transfer_edit';$('#entity-form').dataset.transferId=id;const types=['Traslado Largo','Traslado Depósito','Traslado Directo','Mercosur'];$('#fields').innerHTML=`<div class="field"><label>Tarea</label><input name="task_number" value="${esc(r.task_number)}" required></div><div class="field"><label>Tipo de traslado</label><select name="transfer_type">${types.map(t=>`<option ${t===r.transfer_type?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Fecha</label><input name="scheduled_date" type="date" value="${esc(r.scheduled_date)}" required></div><div class="field"><label>Hora</label><input name="scheduled_time" type="time" value="${esc(r.scheduled_time?.slice(0,5)||'')}"></div><div class="field"><label>Desde</label><input name="origin" value="${esc(r.origin)}" required></div><div class="field"><label>Hacia</label><input name="destination" value="${esc(r.destination)}" required></div><div class="field"><label>Prestador / Auxiliador</label><input name="provider" value="${esc(r.provider||'')}"></div><div class="field full"><label>Comentarios</label><textarea name="comments">${esc(r.comments||'')}</textarea></div>`;$('#modal').showModal()}
function openEditUser(id){const u=window.userCache.find(x=>x.id===id),roles=window.roleCache;$('#modal-title').textContent=`Editar usuario: ${esc(u.username)}`;$('#entity-form').dataset.type='user_edit';$('#entity-form').dataset.userId=id;$('#fields').innerHTML=`<div class="field"><label>Nombre visible</label><input name="display_name" value="${esc(u.display_name)}" required></div><div class="field"><label>Correo corporativo</label><input name="email" type="email" value="${esc(u.email||'')}" placeholder="nombre@portoservicios.com.uy" pattern=".+@portoservicios\\.com\\.uy" required></div><div class="field"><label>Rol</label><select name="role_id">${roles.map(r=>`<option value="${r.id}" ${r.id===u.role_id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>${passwordField('password','Nueva contraseña alternativa (opcional)','Dejar vacío para conservar la actual')}<div class="field full"><label><input name="active" type="checkbox" ${u.active?'checked':''}> Usuario activo</label></div><div class="field full"><small>${u.google_linked?'Cuenta de Google vinculada. Si cambia el correo, deberá vincularse nuevamente.':'La cuenta de Google se vinculará automáticamente en el primer ingreso.'}</small></div>`;$('#modal').showModal()}
async function editRole(id){const role=window.roleCache.find(r=>r.id===id),permissions=window.permissionCache;$('#modal-title').textContent=`Permisos: ${role.name}`;$('#entity-form').dataset.type='role';$('#entity-form').dataset.roleId=id;$('#fields').innerHTML=permissions.map(p=>`<label class="field"><span><input type="checkbox" name="permissions" value="${esc(p.key)}" ${role.permissions.includes(p.key)?'checked':''}> ${esc(p.label)}</span></label>`).join('');$('#modal').showModal()}
const DELAY_DEPARTMENTS=['ARTIGAS','CANELONES','CERRO LARGO','COLONIA','DURAZNO','FLORES','FLORIDA','LAVALLEJA','MALDONADO','MONTEVIDEO','PAYSANDÚ','RÍO NEGRO','RIVERA','ROCHA','SALTO','SAN JOSÉ','SORIANO','TACUAREMBÓ','TREINTA Y TRES'];
const DELAY_SERVICES=['GRÚA','ML','SINIESTROS'];
function clearDelayFilters(){state.delayView='active';state.delayFrom='';state.delayTo='';state.delayDepartment='';state.delayService='';state.delaySearch='';render()}
function delayFilterParams(){const params=new URLSearchParams();if(state.delayFrom)params.set('date_from',state.delayFrom);if(state.delayTo)params.set('date_to',state.delayTo);if(state.delayView==='active')params.set('scope','current');if(state.delayView==='review')params.set('scope','review');if(state.delayView==='history')params.set('scope','normalized');if(state.delayDepartment)params.set('department',state.delayDepartment);if(state.delayService)params.set('service',state.delayService);if(state.delaySearch)params.set('q',state.delaySearch);return params}
function delayMatches(row){if(state.delayView==='active'&&!row.is_current)return false;if(state.delayView==='review'&&!row.needs_review)return false;if(state.delayView==='history'&&row.status!=='NORMALIZADO')return false;const day=String(row.created_at||'').slice(0,10);if(state.delayFrom&&day<state.delayFrom)return false;if(state.delayTo&&day>state.delayTo)return false;if(state.delayDepartment&&normalizeDept(row.department)!==normalizeDept(state.delayDepartment))return false;if(state.delayService&&normalizeDept(row.service)!==normalizeDept(state.delayService))return false;if(state.delaySearch){const q=state.delaySearch.toLowerCase();return [row.service,row.department,row.zone,row.message,row.agent,row.normalized_by,row.resolution_note,row.created_at,row.normalized_at,fmt(row.created_at)].some(value=>String(value||'').toLowerCase().includes(q))}return true}
async function renderDelaysPage(){const reportParams=delayFilterParams(),allRows=await api(`/api/delays?${reportParams}`);window.delayCache=allRows;const rows=allRows.filter(delayMatches);const viewOptions=`<select onchange="state.delayView=this.value;render()"><option value="active" ${state.delayView==='active'?'selected':''}>Vigentes verificadas</option><option value="review" ${state.delayView==='review'?'selected':''}>Requieren revisión</option><option value="history" ${state.delayView==='history'?'selected':''}>Normalizadas / histórico</option><option value="all" ${state.delayView==='all'?'selected':''}>Todas</option></select>`;const filters=`<div class="panel filter-panel"><div class="toolbar"><div class="toolbar-left"><label>Desde <input type="date" value="${esc(state.delayFrom)}" onchange="state.delayFrom=this.value"></label><label>Hasta <input type="date" value="${esc(state.delayTo)}" onchange="state.delayTo=this.value"></label>${viewOptions}<select onchange="state.delayDepartment=this.value"><option value="">Todos los departamentos</option>${DELAY_DEPARTMENTS.map(department=>`<option value="${esc(department)}" ${state.delayDepartment===department?'selected':''}>${esc(department)}</option>`).join('')}</select><select onchange="state.delayService=this.value"><option value="">Todas las prestaciones</option>${DELAY_SERVICES.map(service=>`<option value="${esc(service)}" ${state.delayService===service?'selected':''}>${esc(service)}</option>`).join('')}</select><input class="wide-search" placeholder="Texto, zona, agente o fecha" value="${esc(state.delaySearch)}" oninput="state.delaySearch=this.value" onkeydown="if(event.key==='Enter')render()"><button class="row-action" onclick="render()">Aplicar filtros</button><button class="row-action" onclick="clearDelayFilters()">Limpiar</button></div></div></div>`;const bar=navToolbar(`<strong>${rows.length} zonas</strong>`,`${can('reports.export')?`<button class="row-action" onclick="downloadOperationalReport('delays',new URLSearchParams('${reportParams.toString()}'))">Descargar reporte</button>`:''}${can('delays.create')?'<button class="primary" onclick="openForm(\'delay\')">+ Registrar demora</button>':''}`);$('#content').innerHTML=bar+filters+table([['Registrada',r=>fmt(r.created_at)],['Vigencia',r=>r.status==='NORMALIZADO'?badge(r.status):r.needs_review?'<span class="badge REVIEW_DUE">Requiere revisión</span>':`<span class="badge VIGENTE">Verificada</span><small class="delay-close-meta">hasta ${fmt(r.review_due_at)}</small>`],['Prestación',r=>esc(r.service)],['Departamento',r=>`<strong>${esc(r.department)}</strong>`],['Zona afectada',r=>esc(r.zone)],['Indicación al cliente',r=>esc(r.message==='Margen de'&&r.minutes?`Margen de ${r.minutes} minutos`:r.message)],['Registró',r=>esc(r.agent)],['Cierre',r=>r.status==='NORMALIZADO'?`${esc(r.resolution_note||'Sin detalle')}<small class="delay-close-meta">${esc(r.normalized_by||'—')} · ${fmt(r.normalized_at)}</small>`:'—'],['Acción',r=>r.status==='VIGENTE'&&can('delays.normalize')?`<div class="action-cluster"><button class="row-action" onclick="verifyDelay(${r.id})">${r.needs_review?'Confirmar vigencia':'Renovar control'}</button><button class="row-action danger" onclick="normalizeDelay(${r.id})">Normalizar</button></div>`:'—']],rows,r=>r.needs_review?'delay-review-row':r.is_current?'active-delay':'','No hay demoras para los filtros seleccionados.')}
pages.delays=async()=>{await renderDelaysPage();document.querySelectorAll('#content table tbody tr').forEach((row,index)=>{const item=window.delayCache.filter(delayMatches)[index],cell=row.lastElementChild;if(item&&cell){const button=document.createElement('button');button.className='row-action';button.textContent='Historial';button.onclick=()=>openDelayHistory(item.id);cell.prepend(button)}})};
const renderDashboardBase=pages.dashboard;
pages.dashboard=async()=>{await renderDashboardBase();if(!can('delays.view')||!can('standards.view'))return;try{const alerts=await api('/api/operational-alerts');window.operationalAlerts=alerts;const target=$('.analytics-grid');if(target)target.insertAdjacentHTML('beforebegin',renderOperationalAlerts(alerts))}catch(error){console.warn('No se pudieron cargar las alertas operativas',error)}};
function renderOperationalAlerts(alerts){return `<div class="panel operational-alert-panel"><div class="analytics-head"><div><h2>Alertas operativas</h2><p>Vencimientos, revisiones y propuestas ordenados por urgencia y responsable.</p></div><div><button class="row-action" onclick="filterOperationalAlerts('all')">Todas</button><button class="row-action" onclick="filterOperationalAlerts('mine')">Asignadas a mí</button></div></div><div id="operational-alert-list">${operationalAlertRows(alerts)}</div></div>`}
function operationalAlertRows(alerts){return alerts.length?alerts.map(item=>`<div class="operational-alert ${item.severity==='OVERDUE'?'overdue':'soon'}"><span>${item.kind==='DELAY'?'Demora':item.kind==='STANDARD_APPROVAL'?'Aprobación':'Revisión'}</span><strong>${esc(item.title)}</strong><small>${esc(item.responsible)} · ${item.due_at?fmt(item.due_at):'sin fecha'}</small></div>`).join(''):'<div class="empty">No hay alertas operativas.</div>'}
function filterOperationalAlerts(scope){const alerts=window.operationalAlerts||[],visible=scope==='mine'?alerts.filter(item=>item.responsible===currentUser):alerts;const target=$('#operational-alert-list');if(target)target.innerHTML=operationalAlertRows(visible)}
let timer;function renderDebounced(){clearTimeout(timer);timer=setTimeout(render,250)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.search='';setMobileNavigation(false);render()});$('#supervision-toggle').onclick=()=>{state.supervisionOpen=!state.supervisionOpen;render()};$('#user-button').onclick=logout;
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify(data)});await completeLogin(result)}catch(err){$('#login-error').textContent=err.message}});
const openGenericEntityForm=openForm;
openForm=function(type){if(type!=='transfer')return openGenericEntityForm(type);$('#modal-title').textContent='Nuevo traslado programado';$('#entity-form').dataset.type='transfer';delete $('#entity-form').dataset.transferId;$('#fields').innerHTML=`<div class="field"><label>Tarea</label><input name="task_number" maxlength="120" required></div><div class="field"><label>Tipo de traslado</label><select name="transfer_type">${['Traslado Largo','Traslado Depósito','Traslado Directo','Mercosur'].map(value=>`<option>${esc(value)}</option>`).join('')}</select></div><div class="field"><label>Fecha</label><input name="scheduled_date" type="date" value="${isoDate(new Date())}" required></div><div class="field"><label>Hora <small>Opcional</small></label><input name="scheduled_time" type="time"></div><div class="field"><label>Origen</label><input name="origin" maxlength="500" required></div><div class="field"><label>Destino</label><input name="destination" maxlength="500" required></div><div class="field"><label>Prestador previsto <small>Opcional</small></label><input name="provider" maxlength="200"></div><div class="field full"><label>Comentarios</label><textarea name="comments" maxlength="4000"></textarea></div><div class="field full"><small>Se guardará Sin asignar. Para asignarlo se deberá confirmar prestador y responsable. El sistema controlará datos incompletos, origen y destino iguales y posibles duplicados.</small></div>`;$('#modal').showModal()};
openEditTransfer=async function(id){const r=window.transferCache.find(item=>item.id===id);if(!r)return;try{const people=await api('/api/transfers/responsibles');$('#modal-title').textContent=`Editar programado ${esc(r.task_number)}`;$('#entity-form').dataset.type='transfer_edit';$('#entity-form').dataset.transferId=id;const types=['Traslado Largo','Traslado Depósito','Traslado Directo','Mercosur'];$('#fields').innerHTML=`<div class="field"><label>Tarea</label><input name="task_number" maxlength="120" value="${esc(r.task_number)}" required></div><div class="field"><label>Tipo de traslado</label><select name="transfer_type">${types.map(type=>`<option ${type===r.transfer_type?'selected':''}>${esc(type)}</option>`).join('')}</select></div><div class="field"><label>Fecha</label><input name="scheduled_date" type="date" value="${esc(r.scheduled_date)}" required></div><div class="field"><label>Hora <small>Opcional</small></label><input name="scheduled_time" type="time" value="${esc(r.scheduled_time?.slice(0,5)||'')}"></div><div class="field"><label>Origen</label><input name="origin" maxlength="500" value="${esc(r.origin)}" required></div><div class="field"><label>Destino</label><input name="destination" maxlength="500" value="${esc(r.destination)}" required></div><div class="field"><label>Prestador / Auxiliador</label><input name="provider" maxlength="200" value="${esc(r.provider||'')}"></div><div class="field"><label>Responsable interno</label><select name="responsible"><option value="">Sin asignar</option>${people.map(person=>`<option value="${esc(person.display_name)}" ${person.display_name===r.responsible?'selected':''}>${esc(person.display_name)} · ${esc(person.role_name)}</option>`).join('')}</select></div><div class="field full"><label>Comentarios</label><textarea name="comments" maxlength="4000">${esc(r.comments||'')}</textarea></div><div class="field full"><small>Un programado asignado o en curso debe conservar prestador y responsable.</small></div>`;$('#modal').showModal()}catch(error){toast(error.message)}};
async function bootstrap(){try{authUser=await api('/api/auth/me');currentUser=authUser.display_name;render()}catch{showLogin()}}bootstrap();
